#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Nightly synthetic loop: after the main night queue is done (host back in off mode), run one cycle per graph family
# (structural runs, NIGHT_RUNS_NO_SPLIT inside run_synth.sh) and collect the verdicts. Log: $LD/synth_loop.log
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/synth_loop.log"; }
while ! grep -q "PIPELINES DONE" "$LD/queue.log" 2>/dev/null; do sleep 120; done
log "main queue done; synthetic loop starts"
for D in tests/synth/generated/{chain,tree,star,bipartite,layered,er,ba,cycle}_s1.json; do
  [ -f "$D" ] || continue; N=$(basename "$D" .json)
  log "cycle $N"; bash tests/synth/run_synth.sh "$D" > "$LD/synth_$N.log" 2>&1
  NAME=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['name'])" "$D")
  V=$(grep -h "VERDICT" "$HOME"/fish_traces/synth_runs/verify_${NAME}.txt 2>/dev/null | tail -1)
  log "  $N: ${V:-no verdict} $(grep -h 'false positives' "$HOME"/fish_traces/synth_runs/verify_${NAME}.txt 2>/dev/null | tail -1 | cut -c1-120)"
done
log "SYNTH LOOP DONE"
